def transform(g):
    h,w=len(g),len(g[0])
    fullrows={i for i,r in enumerate(g) if len(set(r))==1}
    fullcols={j for j in range(w) if len({g[i][j] for i in range(h)})==1}
    cand={g[i][0] for i in fullrows}|{g[0][j] for j in fullcols}
    from collections import Counter
    c=Counter(x for r in g for x in r)
    best=None;bn=-1
    for v in cand:
        n=sum(1 for i in fullrows if g[i][0]==v)+sum(1 for j in fullcols if all(g[i][j]==v for i in range(h)))
        if n>bn: bn=n;best=v
    line=best
    out=[row[:] for row in g]
    for i in fullrows:
        if g[i][0]==line:
            out[i]=[2]*w
    for j in fullcols:
        if g[0][j]==line:
            for i in range(h): out[i][j]=2
    return out
